def transform(grid):
    H = len(grid)
    W = len(grid[0])
    start = 6
    if start >= H:
        return grid
    out = [row[:] for row in grid[start:]]
    h = len(out)

    # Parse the four 4x4 header boxes.
    cells = []
    box_cols = [(1, 5), (7, 11), (13, 17), (19, 23)]
    for c0, c1 in box_cols:
        for x in range(c0, c1):
            for y in range(0, 4):
                v = grid[y][x]
                if v not in (0, 5):
                    cells.append((v, y, x - c0))
                    break
            else:
                continue
            break

    # Identify the 2x2 8 marker in the lower part.
    mx = my = None
    for r in range(h - 1):
        for c in range(W - 1):
            if (out[r][c] == 8 and out[r][c + 1] == 8 and
                out[r + 1][c] == 8 and out[r + 1][c + 1] == 8):
                mx, my = c, r
                break
        if mx is not None:
            break

    if mx is None or not cells:
        return out

    # Collect rectangular solid blocks.
    blocks = []
    used = [[False] * W for _ in range(h)]
    for r in range(h):
        for c in range(W):
            if used[r][c]:
                continue
            v = out[r][c]
            if v == 8:
                continue
            # find right/down extents of a rectangle
            c2 = c
            while c2 + 1 < W and out[r][c2 + 1] == v:
                c2 += 1
            r2 = r
            ok = True
            while r2 + 1 < h:
                if any(out[r2 + 1][x] != v for x in range(c, c2 + 1)):
                    ok = False
                    break
                r2 += 1
            if c2 > c and r2 > r and ok:
                for rr in range(r, r2 + 1):
                    for cc in range(c, c2 + 1):
                        if out[rr][cc] == v and not used[rr][cc]:
                            for rr2 in range(r, r2 + 1):
                                for cc2 in range(c, c2 + 1):
                                    used[rr2][cc2] = True
                blocks.append((v, r, c, r2, c2))
                for cc in range(c, c2 + 1):
                    for rr in range(r, r2 + 1):
                        used[rr][cc] = True

    # Match header colors to blocks, choose side by header digit position.
    matches = []
    for v, hy, hx in cells:
        cand = [b for b in blocks if b[0] == v]
        if not cand:
            continue
        # Prefer left/right depending on header x (0..3). For vertical bar use left/right half.
        if hx <= 1:
            side = 0
        else:
            side = 1
        cand.sort(key=lambda b: (abs((b[1] + b[3]) / 2 - my), abs((b[2] + b[4]) / 2 - mx)))
        matches.append((cand[0], side))

    def paint_rect(r0, r1, c0, c1):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if 0 <= r < h and 0 <= c < W and out[r][c] not in (2, 3, 4, 6, 9):
                    pass
                if 0 <= r < h and 0 <= c < W:
                    if out[r][c] in (0, 5) or out[r][c] not in (2, 3, 4, 6, 9):
                        if out[r][c] not in (2, 3, 4, 6, 9):
                            pass
        # Simpler: paint only background-like cells. Determine background as most common non-8 color in out.
        pass

    # Determine background color as most frequent non-8, non-header-block color.
    from collections import Counter  # not allowed, avoid import; use dict
    cnt = {}
    for row in out:
        for v in row:
            if v != 8:
                cnt[v] = cnt.get(v, 0) + 1
    bg = 0
    best = -1
    for v, n in cnt.items():
        if n > best:
            best = n
            bg = v

    def paint(r0, r1, c0, c1):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if 0 <= r < h and 0 <= c < W and out[r][c] == bg:
                    out[r][c] = 8

    # Connect marker to each matched block along horizontal/vertical axis.
    m_r0, m_r1 = my, my + 1
    m_c0, m_c1 = mx, mx + 1

    for (bv, br0, bc0, br1, bc1), side in matches:
        # Determine horizontal span between marker and block side.
        if br1 < m_r0:
            # block above marker
            r0 = br1
            r1 = m_r0 - 1
            if side == 0:
                c0 = min(bc0, m_c0)
                c1 = max(bc0, m_c1)
            else:
                c0 = min(bc1, m_c0)
                c1 = max(bc1, m_c1)
            # vertical strip connecting
            paint(r0, r1, m_c0, m_c1)
            # horizontal strip at block edge
            if side == 0:
                paint(br1, br1, min(bc0, m_c0), max(bc1, m_c1))
            else:
                paint(br1, br1, min(bc1, m_c0), max(bc0, m_c1))
        elif br0 > m_r1:
            r0 = m_r1 + 1
            r1 = br0
            if side == 0:
                c0 = min(bc0, m_c0)
                c1 = max(bc0, m_c1)
            else:
                c0 = min(bc1, m_c0)
                c1 = max(bc1, m_c1)
            paint(r0, r1, m_c0, m_c1)
            if side == 0:
                paint(br0, br0, min(bc0, m_c0), max(bc1, m_c1))
            else:
                paint(br0, br0, min(bc1, m_c0), max(bc0, m_c1))
        else:
            # vertical overlap: connect horizontally to side
            if side == 0:
                c0 = min(bc1, m_c0)
                c1 = max(bc1, m_c0)
                r0 = max(br0, m_r0)
                r1 = min(br1, m_r1)
                paint(r0, r1, c0, c1)
            else:
                c0 = min(bc0, m_c1)
                c1 = max(bc0, m_c1)
                r0 = max(br0, m_r0)
                r1 = min(br1, m_r1)
                paint(r0, r1, c0, c1)

    # Draw a full-width/height frame around marker and connected side strips based on extremes of all matches.
    top = min([br1 for (bv, br0, bc0, br1, bc1), side in matches] + [m_r0])
    bottom = max([br0 for (bv, br0, bc0, br1, bc1), side in matches] + [m_r1])
    left = min([bc0 for (bv, br0, bc0, br1, bc1), side in matches] + [m_c0])
    right = max([bc1 for (bv, br0, bc0, br1, bc1), side in matches] + [m_c1])

    # Horizontal bars through marker rows across full left-right extent
    paint(m_r0, m_r1, left, right)
    # Vertical bars through marker cols across full top-bottom extent
    paint(top, bottom, m_c0, m_c1)

    # Extend side vertical/horizontal bars to form outer boundaries as seen in demos.
    for (bv, br0, bc0, br1, bc1), side in matches:
        if side == 0:
            # left side bar at block's left column extended top-bottom
            paint(top, bottom, bc0, min(bc0 + 1, W - 1))
        else:
            # right side bar at block's right column extended top-bottom
            paint(top, bottom, max(bc1 - 1, 0), bc1)

    # Horizontal top/bottom boundaries already partly; make complete left-right bars at top/bottom if supported
    paint(top, top, left, right)
    paint(bottom, bottom, left, right)

    return out
